/*
 * arcus_extras.c — the embedded extras' catalog; see arcus_extras.h.
 *
 * extras_embed.S (generated by CMakeLists.txt) holds every book's pages in one blob, an
 * offsets table (count + 1 entries) and a catalog string, one line per book in folder
 * order: "<pages>|<kind>|<group>|<title>|<detail...>" (the detail may hold more '|').
 */
#include "arcus_extras.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

extern const char arcus_extras_catalog[];
extern const uint8_t arcus_extras_data[];
extern const uint32_t arcus_extras_offsets[];
extern const uint32_t arcus_extras_count;

#define BOOKS_MAX 32

static ArcusBook s_books[BOOKS_MAX];
static int s_n = -1;

static void copy_field(char *dst, size_t n, const char *src, size_t len)
{
    if (len >= n) len = n - 1;
    memcpy(dst, src, len);
    dst[len] = 0;
}

static void load(void)
{
    if (s_n >= 0) return;
    s_n = 0;
    if (getenv("ARCUS_NO_EXTRAS") && getenv("ARCUS_NO_EXTRAS")[0] == '1') return;
    const char *p = arcus_extras_catalog;
    int first = 0;
    while (*p && s_n < BOOKS_MAX) {
        const char *end = strchr(p, '\n');
        if (!end) end = p + strlen(p);
        const char *f[4];
        size_t fl[4];
        int count = atoi(p), k = 0;
        const char *q = strchr(p, '|');
        while (q && q < end && k < 4) {
            const char *next = memchr(q + 1, '|', (size_t)(end - q - 1));
            f[k] = q + 1;
            fl[k] = (size_t)((k == 3 || !next ? end : next) - (q + 1));   /* the detail keeps its '|' */
            k++;
            q = k == 4 ? NULL : next;
        }
        if (k >= 3 && count > 0 && first + count <= (int)arcus_extras_count) {
            ArcusBook *b = &s_books[s_n++];
            memset(b, 0, sizeof *b);
            b->kind = fl[0] == 6 && !memcmp(f[0], "scroll", 6) ? ARCUS_BOOK_SCROLL : ARCUS_BOOK_PAGES;
            copy_field(b->group, sizeof b->group, f[1], fl[1]);
            copy_field(b->title, sizeof b->title, f[2], fl[2]);
            if (k == 4) copy_field(b->detail, sizeof b->detail, f[3], fl[3]);
            b->first = first;
            b->count = count;
        }
        first += count > 0 ? count : 0;
        p = *end ? end + 1 : end;
    }
}

int arcus_extras_books(void)
{
    load();
    return s_n;
}

const ArcusBook *arcus_extras_book(int i)
{
    load();
    return i >= 0 && i < s_n ? &s_books[i] : NULL;
}

int arcus_extras_find(const char *group)
{
    load();
    for (int i = 0; i < s_n; i++)
        if (!strcmp(s_books[i].group, group)) return i;
    return -1;
}

int arcus_extras_group_count(const char *group)
{
    load();
    int n = 0;
    for (int i = 0; i < s_n; i++) n += !strcmp(s_books[i].group, group);
    return n;
}

int arcus_extras_page(int book, int page, const uint8_t **data, size_t *len)
{
    const ArcusBook *b = arcus_extras_book(book);
    if (!b || page < 0 || page >= b->count) return 0;
    int g = b->first + page;
    *data = arcus_extras_data + arcus_extras_offsets[g];
    *len = arcus_extras_offsets[g + 1] - arcus_extras_offsets[g];
    return 1;
}
